const MAX_TITLE_LENGTH = 255;
const MAX_FALLBACK_TITLE_LENGTH = 60;

/**
 * Budget for a one-line title. Reasoning models spend most of it on thinking tokens before
 * writing anything, and a budget too small for that comes back as an empty response.
 */
export const TITLE_MAX_OUTPUT_TOKENS = 1024;

/** Models answer with a bare line that is often quoted or longer than the prompt asked for. */
export function sanitizeTitle(text: string): string {
	const firstLine = firstNonEmptyLine(text);
	return truncate(firstLine.replace(/^["'`]+|["'`]+$/g, '').trim(), MAX_TITLE_LENGTH);
}

/** A title taken from the prompt itself, for when the model returns nothing usable. */
export function titleFromPrompt(prompt: string): string {
	return truncate(firstNonEmptyLine(prompt), MAX_FALLBACK_TITLE_LENGTH);
}

function firstNonEmptyLine(text: string): string {
	return text.trim().split(/\r?\n/, 1)[0]?.trim() ?? '';
}

function truncate(title: string, maxLength: number): string {
	return title.length > maxLength ? `${title.slice(0, maxLength - 3)}...` : title;
}

